namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on floured surface.", "Spread crushed tomatoes over dough.", "Add torn mozzarella pieces.", "Bake 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or pan-fry chicken until charred.", "Sauté garlic and ginger in butter.", "Add tomato sauce and simmer 10 minutes.", "Stir in cream and cooked chicken.", "Simmer 5 more minutes and serve with rice."],
            AverageRating = 4.8, RatingCount = 24
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm taco shells in oven.", "Fill shells with beef.", "Top with lettuce, tomato, cheese, and sour cream."],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 4, Title = "Pad Thai", Category = "Asian",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce"],
            Steps = ["Soak rice noodles in warm water 30 minutes.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in wok.", "Add drained noodles, tamarind paste, and fish sauce.", "Toss with shrimp, bean sprouts, and green onions.", "Serve topped with crushed peanuts and lime wedge."],
            AverageRating = 4.6, RatingCount = 15
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F. Butter ramekins and dust with cocoa.", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla until thick.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into ramekins and bake 12-14 minutes.", "Invert onto plates and serve immediately."],
            AverageRating = 4.9, RatingCount = 30
        },
        new()
        {
            Id = 6, Title = "Caesar Salad", Category = "Salads",
            Ingredients = ["Romaine lettuce", "Parmesan cheese", "Croutons", "Caesar dressing", "Lemon juice", "Anchovy paste"],
            Steps = ["Wash and chop romaine lettuce.", "Make dressing: whisk anchovy paste, lemon juice, garlic, and olive oil.", "Toss lettuce with dressing.", "Top with shaved parmesan and croutons.", "Serve immediately."],
            AverageRating = 3.9, RatingCount = 6
        }
    ];

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

